{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/schema/incident-record.schema.json",
  "title": "Halcyon Threshold synthetic frontier incident record",
  "description": "Experimental record structure for discussing early notification and later investigation. Version 0.1.0 is for synthetic examples only. Validation checks structure and selected consistency rules, not truth, legal reportability, completeness, or safety.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "record_id",
    "record_status",
    "record_kind",
    "synthetic",
    "supersedes",
    "reported_at",
    "last_updated_at",
    "timing",
    "model",
    "affected_contexts",
    "triggers",
    "event_class",
    "severity",
    "narrative",
    "harm",
    "containment",
    "evidence",
    "notifications",
    "corrections",
    "follow_up",
    "disclosure",
    "extensions"
  ],
  "properties": {
    "schema_version": {
      "const": "0.1.0"
    },
    "record_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$",
      "description": "Opaque record identifier; do not encode a person, customer, or secret."
    },
    "record_status": {
      "type": "string",
      "enum": ["initial", "update", "final", "withdrawn"]
    },
    "record_kind": {
      "type": "string",
      "enum": ["incident", "near_miss", "drill"]
    },
    "synthetic": {
      "const": true,
      "description": "This prototype accepts fictional records only."
    },
    "supersedes": {
      "type": ["string", "null"],
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$",
      "description": "Identifier of the immediately prior record. Null only for an initial record. Never overwrite the prior report."
    },
    "reported_at": {
      "type": "string",
      "format": "date-time",
      "description": "Original notification time; remains unchanged across revisions."
    },
    "last_updated_at": {
      "type": "string",
      "format": "date-time"
    },
    "timing": { "$ref": "#/$defs/timing" },
    "model": { "$ref": "#/$defs/model" },
    "affected_contexts": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": ["development", "evaluation", "staging", "production", "third_party", "unknown"]
      }
    },
    "triggers": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": ["external_report", "automated_monitor", "human_observation", "evaluation", "red_team", "deployer_notification", "other", "unknown"]
      }
    },
    "event_class": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": ["loss_of_control", "safeguard_bypass", "unauthorized_access_or_exfiltration", "hazardous_capability_misuse", "critical_system_disruption", "harmful_output_or_decision", "security_compromise", "evaluation_anomaly", "other", "unknown"]
      },
      "description": "Descriptive tags, not findings of intent, causation, or legal category."
    },
    "severity": { "$ref": "#/$defs/severity" },
    "narrative": { "$ref": "#/$defs/narrative" },
    "harm": { "$ref": "#/$defs/harm" },
    "containment": { "$ref": "#/$defs/containment" },
    "evidence": {
      "type": "array",
      "items": { "$ref": "#/$defs/evidence_item" },
      "description": "References to governed evidence, not embedded logs or sensitive content."
    },
    "notifications": { "$ref": "#/$defs/notifications" },
    "corrections": { "$ref": "#/$defs/corrections" },
    "follow_up": { "$ref": "#/$defs/follow_up" },
    "disclosure": { "$ref": "#/$defs/disclosure" },
    "extensions": {
      "type": "object",
      "additionalProperties": false,
      "patternProperties": {
        "^x-[a-z0-9][a-z0-9._-]*$": {}
      },
      "description": "Optional experimental fields with x- prefixed names. Extensions are not part of the common record and must not silently become mandatory."
    }
  },
  "$defs": {
    "nullable_datetime": {
      "type": ["string", "null"],
      "format": "date-time"
    },
    "timing": {
      "type": "object",
      "additionalProperties": false,
      "required": ["occurred_start", "occurred_end", "detected_at", "awareness_at", "basis", "notes"],
      "properties": {
        "occurred_start": { "$ref": "#/$defs/nullable_datetime" },
        "occurred_end": { "$ref": "#/$defs/nullable_datetime" },
        "detected_at": { "$ref": "#/$defs/nullable_datetime" },
        "awareness_at": {
          "type": "string",
          "format": "date-time",
          "description": "When the reporting organization first had information that could reasonably trigger its internal escalation process. The applicable legal clock must be defined by the rule, not by this field."
        },
        "basis": {
          "type": "string",
          "enum": ["observed", "inferred", "mixed", "unknown"]
        },
        "notes": {
          "type": "string",
          "minLength": 1,
          "maxLength": 4000
        }
      }
    },
    "model": {
      "type": "object",
      "additionalProperties": false,
      "required": ["developer_label", "model_label", "version_or_snapshot", "deployment_label"],
      "properties": {
        "developer_label": { "type": "string", "minLength": 1, "maxLength": 200 },
        "model_label": { "type": "string", "minLength": 1, "maxLength": 200 },
        "version_or_snapshot": { "type": ["string", "null"], "maxLength": 300 },
        "deployment_label": { "type": "string", "minLength": 1, "maxLength": 300 }
      }
    },
    "severity": {
      "type": "object",
      "additionalProperties": false,
      "required": ["reportable", "rationale", "level", "classification_confidence"],
      "properties": {
        "reportable": {
          "type": "boolean",
          "description": "Reporter's provisional classification, not a legal determination by the checker."
        },
        "rationale": { "type": "string", "minLength": 1, "maxLength": 6000 },
        "level": {
          "type": "string",
          "enum": ["critical", "high", "moderate", "low", "undetermined"]
        },
        "classification_confidence": {
          "type": "string",
          "enum": ["high", "medium", "low", "unknown"]
        }
      }
    },
    "narrative": {
      "type": "object",
      "additionalProperties": false,
      "required": ["observed", "suspected_causes", "unknowns"],
      "properties": {
        "observed": {
          "type": "string",
          "minLength": 1,
          "maxLength": 12000,
          "description": "Observations and measurements, kept distinct from causal interpretation."
        },
        "suspected_causes": {
          "type": "string",
          "minLength": 1,
          "maxLength": 12000,
          "description": "Hypotheses with confidence, or an explicit statement that no cause has been established."
        },
        "unknowns": {
          "type": "string",
          "minLength": 1,
          "maxLength": 12000
        }
      }
    },
    "harm": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status", "domains", "description", "affected_population", "estimated_scale", "reversible"],
      "properties": {
        "status": {
          "type": "string",
          "enum": ["realized", "potential", "none_identified", "unknown"]
        },
        "domains": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": ["people", "critical_infrastructure", "environment", "rights", "property", "security", "epistemic", "other", "none", "unknown"]
          }
        },
        "description": { "type": "string", "minLength": 1, "maxLength": 12000 },
        "affected_population": { "type": "string", "minLength": 1, "maxLength": 4000 },
        "estimated_scale": {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "unit", "basis"],
          "properties": {
            "value": { "type": ["number", "null"], "minimum": 0 },
            "unit": { "type": ["string", "null"], "maxLength": 100 },
            "basis": { "type": "string", "enum": ["measured", "estimated", "unknown"] }
          }
        },
        "reversible": { "type": "string", "enum": ["yes", "no", "partial", "unknown"] }
      }
    },
    "containment": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status", "actions", "residual_risk"],
      "properties": {
        "status": {
          "type": "string",
          "enum": ["contained", "mitigated", "in_progress", "not_started", "not_applicable", "unknown"]
        },
        "actions": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["description", "status", "observed_effect"],
            "properties": {
              "description": { "type": "string", "minLength": 1, "maxLength": 4000 },
              "status": { "type": "string", "enum": ["planned", "in_progress", "complete", "failed", "unknown"] },
              "observed_effect": { "type": ["string", "null"], "maxLength": 4000 }
            }
          }
        },
        "residual_risk": { "type": "string", "minLength": 1, "maxLength": 6000 }
      }
    },
    "evidence_item": {
      "type": "object",
      "additionalProperties": false,
      "required": ["evidence_id", "description", "kind", "acquired_at", "integrity", "location_reference", "access", "sha256"],
      "properties": {
        "evidence_id": { "type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$" },
        "description": { "type": "string", "minLength": 1, "maxLength": 4000 },
        "kind": { "type": "string", "enum": ["logs", "eval_result", "report", "screenshot", "artifact", "external_reference", "other"] },
        "acquired_at": { "$ref": "#/$defs/nullable_datetime" },
        "integrity": { "type": "string", "enum": ["verified", "unverified", "not_applicable"] },
        "location_reference": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Governed pointer only. Do not embed credentials, raw restricted logs, or secret URLs in public records."
        },
        "access": { "type": "string", "enum": ["synthetic", "regulator_only", "restricted", "public"] },
        "sha256": { "type": ["string", "null"], "pattern": "^[0-9a-f]{64}$" }
      }
    },
    "notifications": {
      "type": "object",
      "additionalProperties": false,
      "required": ["regulator_notified", "regulator_reference", "deployer_notification"],
      "properties": {
        "regulator_notified": { "type": "boolean" },
        "regulator_reference": { "type": ["string", "null"], "maxLength": 300 },
        "deployer_notification": { "type": "string", "enum": ["not_required", "completed", "planned", "unknown"] }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/schema/corrections.schema.json",
  "title": "Correction and revision fragment",
  "description": "This file documents the corrections fragment referenced by the incident record. Validate complete records against incident-record.schema.json; the reference checker inlines these definitions.",
  "type": "object",
  "additionalProperties": false,
  "required": ["change_summary", "correction_of_prior_error", "correction_note"],
  "properties": {
    "change_summary": {
      "type": "string",
      "minLength": 1,
      "maxLength": 6000
    },
    "correction_of_prior_error": {
      "type": "boolean"
    },
    "correction_note": {
      "type": ["string", "null"],
      "maxLength": 6000,
      "description": "Required and non-empty whenever correction_of_prior_error is true. State what changed and why; do not erase the original."
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2026-12/schema",
