    },
    "investigation_status": {
      "type": "string",
      "enum": ["not_started", "in_progress", "complete", "blocked", "not_applicable"]
    },
    "owner_role": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200,
      "description": "Accountable role, not a person's name or direct contact information."
    },
    "lessons": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 4000
      }
    }
  }
}

