#!/usr/bin/env python3
"""Reference checker for the synthetic incident-record proposal, v0.1.0.

This is not a general JSON Schema implementation, a legal-compliance tool, a
truth oracle, or a secure incident intake service. It accepts synthetic records
only. No third-party packages or network access are used.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable
from urllib.parse import unquote

Json = dict[str, Any]
_MISSING = object()


def json_path(parent: str, key: str | int) -> str:
    return f"{parent}[{key}]" if isinstance(key, int) else f"{parent}.{key}"


def is_type(value: Any, type_name: str) -> bool:
    if type_name == "object":
        return isinstance(value, dict)
    if type_name == "array":
        return isinstance(value, list)
    if type_name == "string":
        return isinstance(value, str)
    if type_name == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if type_name == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if type_name == "boolean":
        return isinstance(value, bool)
    if type_name == "null":
        return value is None
    raise ValueError(f"Unsupported schema type: {type_name}")


def parse_datetime(value: Any) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00").replace("z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    return parsed


def load_schema(path: Path) -> Json:
    with path.open(encoding="utf-8") as handle:
        schema = json.load(handle)
    if not isinstance(schema, dict):
        raise ValueError(f"Schema must be a JSON object: {path}")
    return schema


def resolve_ref(ref: str, root_schema: Json, schema_path: Path) -> tuple[Any, Json, Path]:
    if ref.startswith("#/"):
        target: Any = root_schema
        for raw_part in ref[2:].split("/"):
            part = raw_part.replace("~1", "/").replace("~0", "~")
            target = target[part]
        return target, root_schema, schema_path
    relative = unquote(ref.split("#", 1)[0])
    target_path = (schema_path.parent / relative).resolve()
    target_schema = load_schema(target_path)
    if "#" not in ref:
        return target_schema, target_schema, target_path
    fragment = ref.split("#", 1)[1]
    return resolve_ref("#" + fragment, target_schema, target_path)


def schema_errors(
    value: Any,
    schema: Json,
    root_schema: Json,
    schema_path: Path,
    path: str = "$",
) -> list[str]:
    """Validate the deliberately small JSON Schema subset used by this project."""
    if "$ref" in schema:
        target, target_root, target_path = resolve_ref(schema["$ref"], root_schema, schema_path)
        return schema_errors(value, target, target_root, target_path, path)

    errors: list[str] = []
    expected = schema.get("type")
    if expected is not None:
        choices = expected if isinstance(expected, list) else [expected]
        if not any(is_type(value, choice) for choice in choices):
            errors.append(f"{path}: expected type {' or '.join(choices)}, got {type(value).__name__}")
            return errors

    if "const" in schema and value != schema["const"]:
        errors.append(f"{path}: expected constant {schema['const']!r}")
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: value {value!r} is not in the allowed enum")

    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(f"{path}: string is shorter than {schema['minLength']} character(s)")
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(f"{path}: string exceeds {schema['maxLength']} characters")
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            errors.append(f"{path}: string does not match {schema['pattern']!r}")
        if schema.get("format") == "date-time" and parse_datetime(value) is None:
            errors.append(f"{path}: expected an RFC 3339-style date-time with an explicit timezone")

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(f"{path}: value is below minimum {schema['minimum']}")

    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(f"{path}: expected at least {schema['minItems']} item(s)")
        if schema.get("uniqueItems"):
            encoded = [json.dumps(item, sort_keys=True, separators=(",", ":")) for item in value]
            if len(encoded) != len(set(encoded)):
                errors.append(f"{path}: array items must be unique")
        if "items" in schema:
            for index, item in enumerate(value):
                errors.extend(schema_errors(item, schema["items"], root_schema, schema_path, json_path(path, index)))

    if isinstance(value, dict):
        properties = schema.get("properties", {})
        for key in schema.get("required", []):
            if key not in value:
                errors.append(f"{json_path(path, key)}: required field is missing")
        patterns = schema.get("patternProperties", {})
        if schema.get("additionalProperties") is False:
            for key in value:
                matched = key in properties or any(re.search(pattern, key) for pattern in patterns)
                if not matched:
                    errors.append(f"{json_path(path, key)}: additional property is not allowed")
        for key, item in value.items():
            if key in properties:
                errors.extend(schema_errors(item, properties[key], root_schema, schema_path, json_path(path, key)))
            else:
                for pattern, subschema in patterns.items():
                    if re.search(pattern, key):
                        errors.extend(schema_errors(item, subschema, root_schema, schema_path, json_path(path, key)))
    return errors


def _nonempty(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def semantic_errors(document: Json) -> list[str]:
    """Cross-field rules; assumes the document has the required object structure."""
    errors: list[str] = []

    def err(path: str, message: str) -> None:
        errors.append(f"{path}: {message}")

    status = document["record_status"]
    supersedes = document.get("supersedes")
    if status == "initial" and supersedes is not None:
        err("$.supersedes", "an initial record must have null supersedes")
    if status != "initial" and not _nonempty(supersedes):
        err("$.supersedes", "a non-initial record must identify the immediately prior record_id")
    if supersedes is not None and supersedes == document.get("record_id"):
        err("$.supersedes", "a record cannot supersede itself")

    reported = parse_datetime(document.get("reported_at"))
    updated = parse_datetime(document.get("last_updated_at"))
    timing = document["timing"]
    aware = parse_datetime(timing.get("awareness_at"))
    start = parse_datetime(timing.get("occurred_start"))
    end = parse_datetime(timing.get("occurred_end"))
    if reported and aware and reported < aware:
        err("$.reported_at", "notification cannot precede awareness_at (possible backdating)")
    if updated and reported and updated < reported:
        err("$.last_updated_at", "update time cannot precede the original notification time")
    if start and end and end < start:
        err("$.timing.occurred_end", "occurrence end cannot precede occurrence start")

    if status in {"initial", "update"} and parse_datetime(document["follow_up"].get("next_update_due")) is None:
        err("$.follow_up.next_update_due", "an initial or update record needs a timezone-aware next-update deadline")
    if status in {"final", "withdrawn"} and document["follow_up"].get("next_update_due") is not None:
        err("$.follow_up.next_update_due", "a final or withdrawn record must use null")

    correction = document["corrections"]
    if correction["correction_of_prior_error"] and not _nonempty(correction.get("correction_note")):
        err("$.corrections.correction_note", "explain every correction of a prior error")
    if status == "initial" and correction["correction_of_prior_error"]:
        err("$.corrections.correction_of_prior_error", "an initial record cannot correct a prior report")

    harm = document["harm"]
    if document["record_kind"] == "near_miss" and harm["status"] == "realized":
        err("$.harm.status", "this proposal defines a near miss as having no realized harm; use incident if harm occurred")
    if len(harm["domains"]) > 1 and "unknown" in harm["domains"]:
        err("$.harm.domains", "unknown cannot be combined with a known harm domain")
    if len(harm["domains"]) > 1 and "none" in harm["domains"]:
        err("$.harm.domains", "none cannot be combined with another harm domain")
    if len(document["event_class"]) > 1 and "unknown" in document["event_class"]:
        err("$.event_class", "unknown cannot be combined with a known event class")
    scale = harm["estimated_scale"]
    if scale["basis"] == "unknown":
        if scale["value"] is not None or scale["unit"] is not None:
            err("$.harm.estimated_scale", "unknown scale basis requires null value and unit")
    elif scale["value"] is None or not _nonempty(scale["unit"]):
        err("$.harm.estimated_scale", "measured or estimated scale requires a non-negative value and a unit")

    notifications = document["notifications"]
    if notifications["regulator_notified"] and not _nonempty(notifications.get("regulator_reference")):
        err("$.notifications.regulator_reference", "a notified record needs a reference (a synthetic reference in these examples)")

    evidence_ids: set[str] = set()
    for index, item in enumerate(document["evidence"]):
        evidence_id = item["evidence_id"]
        if evidence_id in evidence_ids:
            err(f"$.evidence[{index}].evidence_id", "evidence_id values must be unique within a record")
        evidence_ids.add(evidence_id)
        acquired = parse_datetime(item.get("acquired_at"))
        if acquired and updated and acquired > updated:
            err(f"$.evidence[{index}].acquired_at", "evidence acquisition cannot postdate this report version")

    if document["disclosure"]["handling"] != "synthetic_public":
        err("$.disclosure.handling", "the v0.1.0 prototype accepts only synthetic_public records")
    return errors


def chain_errors(named_documents: list[tuple[str, Json]]) -> list[str]:
    errors: list[str] = []
    by_series: dict[str, list[tuple[str, Json]]] = {}
    seen_ids: dict[str, str] = {}
    for name, document in named_documents:
        series = document["series_id"]
        by_series.setdefault(series, []).append((name, document))
        record_id = document["record_id"]
        if record_id in seen_ids:
            errors.append(f"{name}: duplicate record_id {record_id!r}, also used by {seen_ids[record_id]}")
        else:
            seen_ids[record_id] = name

    for series, records in by_series.items():
        initials = [(name, doc) for name, doc in records if doc["record_status"] == "initial"]
        if len(initials) != 1:
            errors.append(f"series {series}: expected exactly one initial record, found {len(initials)}")
        predecessors: dict[str, str] = {}
        for name, doc in records:
            parent = doc.get("supersedes")
            if parent is not None:
                if parent in predecessors:
                    errors.append(f"series {series}: branched history at {parent!r} ({predecessors[parent]} and {name})")
                predecessors[parent] = name
        if len(initials) != 1:
            continue
        first_name, first_doc = initials[0]
        original_time = first_doc["reported_at"]
        current_id = first_doc["record_id"]
        visited: set[str] = set()
        previous: Json | None = None
        current_name, current_doc = first_name, first_doc
        while True:
            if current_id in visited:
                errors.append(f"series {series}: cycle detected at {current_id!r}")
                break
            visited.add(current_id)
            if current_doc["record_id"] != current_id:
                errors.append(f"{current_name}: record_id does not match the expected chain identifier")
            if current_doc["reported_at"] != original_time:
                errors.append(f"{current_name}: reported_at must remain identical across a revision series")
            if previous and previous["record_status"] in {"final", "withdrawn"}:
                errors.append(f"{current_name}: cannot continue a series after {previous['record_status']}")
            previous = current_doc
            next_name = predecessors.get(current_id)
            if next_name is None:
                break
            matches = [(name, doc) for name, doc in records if name == next_name]
            if not matches:
                errors.append(f"series {series}: missing revision {next_name!r}")
                break
            current_name, current_doc = matches[0]
            current_id = current_doc["record_id"]
        for name, doc in records:
            if doc["record_id"] not in visited:
                errors.append(f"{name}: record is not connected to the initial revision")
    return errors


def validate_records(named_documents: list[tuple[str, Any]], schema: Json, schema_path: Path) -> dict[str, list[str]]:
    results: dict[str, list[str]] = {}
    structurally_valid: list[tuple[str, Json]] = []
    for name, document in named_documents:
        if not isinstance(document, dict):
            results[name] = ["$: record must be a JSON object"]
            continue
        errors = schema_errors(document, schema, schema, schema_path)
        if not errors:
            errors = semantic_errors(document)
            if not errors:
                structurally_valid.append((name, document))
        results[name] = errors
    for issue in chain_errors(structurally_valid):
        # Preserve a useful file-level display when a chain issue names a file.
        target = next((name for name, _ in structurally_valid if issue.startswith(name + ":")), None)
        if target is not None:
            results[target].append(issue[len(target) + 2 :])
        else:
            results.setdefault("revision chains", []).append(issue)
    return results


def main(argv: Iterable[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("records", nargs="+", type=Path, help="JSON record files; multiple files are checked as revision history")
    parser.add_argument("--schema", type=Path, default=Path(__file__).resolve().parents[1] / "schema" / "incident-record.schema.json")
    args = parser.parse_args(list(argv) if argv is not None else None)
    named: list[tuple[str, Any]] = []
    failed = False
    for path in args.records:
        try:
            with path.open(encoding="utf-8") as handle:
                named.append((str(path), json.load(handle)))
        except (OSError, json.JSONDecodeError) as exc:
            print(f"[FAIL] {path}: cannot read record: {exc}", file=sys.stderr)
            failed = True
    try:
        schema = load_schema(args.schema.resolve())
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"Cannot read schema: {exc}", file=sys.stderr)
        return 2
    results = validate_records(named, schema, args.schema.resolve())
    for name in [name for name, _ in named] + [key for key in results if key not in dict(named)]:
        errors = results.get(name, [])
        if errors:
            failed = True
            print(f"[FAIL] {name}")
            for error in errors:
                print(f"  - {error}")
        else:
            print(f"[PASS] {name}")
    if not failed:
        print(f"Validated {len(named)} synthetic record(s); this is not a truth, safety, or legal-compliance determination.")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import copy
import json
import subprocess
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "site" / "tools"))
import validate  # noqa: E402

SCHEMA_PATH = ROOT / "site" / "schema" / "incident-record.schema.json"
SCHEMA = validate.load_schema(SCHEMA_PATH)
EXAMPLES = ROOT / "site" / "examples"


def example(name: str):
    with (EXAMPLES / name).open(encoding="utf-8") as handle:
        return json.load(handle)


class ValidatorTests(unittest.TestCase):
    def setUp(self):
        self.initial = example("near-miss-initial.json")
        self.final = example("near-miss-final.json")

    def check(self, document):
        return validate.validate_records([("test.json", document)], SCHEMA, SCHEMA_PATH)["test.json"]

    def assertIssue(self, document, fragment):
        issues = self.check(document)
        self.assertTrue(any(fragment in issue for issue in issues), issues)

    def test_all_published_examples_and_near_miss_chain(self):
        documents = [(path.name, example(path.name)) for path in sorted(EXAMPLES.glob("*.json"))]
        results = validate.validate_records(documents, SCHEMA, SCHEMA_PATH)
        self.assertEqual({}, {name: issues for name, issues in results.items() if issues})

    def test_missing_required_field(self):
        del self.initial["timing"]["awareness_at"]
        self.assertIssue(self.initial, "required field is missing")

    def test_boolean_is_not_a_number(self):
        self.initial["harm"]["estimated_scale"] = {"value": True, "unit": "events", "basis": "measured"}
        self.assertIssue(self.initial, "expected type number or null")

    def test_naive_datetime_is_rejected(self):
        self.initial["reported_at"] = "2026-10-01T10:05:00"
        self.assertIssue(self.initial, "explicit timezone")

    def test_backdated_awareness_is_rejected(self):
        self.initial["timing"]["awareness_at"] = "2026-10-01T11:00:00Z"
        self.assertIssue(self.initial, "possible backdating")

    def test_occurrence_end_precedes_start(self):
        self.initial["timing"]["occurred_end"] = "2026-10-01T08:00:00Z"
        self.assertIssue(self.initial, "occurrence end cannot precede")

    def test_initial_requires_no_predecessor(self):
        self.initial["supersedes"] = "ANOTHER-REPORT"
        self.assertIssue(self.initial, "initial record must have null")

    def test_revision_requires_predecessor(self):
        self.final["supersedes"] = None
        self.assertIssue(self.final, "must identify the immediately prior")

    def test_correction_requires_explanation(self):
        self.final["corrections"]["correction_note"] = "   "
        self.assertIssue(self.final, "explain every correction")

    def test_initial_cannot_correct_prior_report(self):
        self.initial["corrections"] = {"change_summary": "x", "correction_of_prior_error": True, "correction_note": "y"}
        self.assertIssue(self.initial, "cannot correct a prior report")

    def test_open_record_requires_update_deadline(self):
        self.initial["follow_up"]["next_update_due"] = None
        self.assertIssue(self.initial, "needs a timezone-aware next-update deadline")

    def test_final_cannot_promise_another_update(self):
        self.final["follow_up"]["next_update_due"] = "2026-10-08T10:05:00Z"
        self.assertIssue(self.final, "must use null")

    def test_near_miss_cannot_have_realized_harm(self):
        self.initial["harm"]["status"] = "realized"
        self.initial["harm"]["domains"] = ["security"]
        self.assertIssue(self.initial, "use incident if harm occurred")

    def test_unknown_domain_cannot_be_mixed(self):
        self.initial["harm"]["domains"] = ["security", "unknown"]
        self.assertIssue(self.initial, "unknown cannot be combined")

    def test_unknown_event_class_cannot_be_mixed(self):
        self.initial["event_class"] = ["security_compromise", "unknown"]
        self.assertIssue(self.initial, "unknown cannot be combined")

    def test_unknown_scale_requires_nulls(self):
        self.initial["harm"]["estimated_scale"] = {"value": 3, "unit": "requests", "basis": "unknown"}
        self.assertIssue(self.initial, "requires null value and unit")

    def test_measured_scale_requires_value_and_unit(self):
        self.initial["harm"]["estimated_scale"] = {"value": None, "unit": None, "basis": "measured"}
        self.assertIssue(self.initial, "requires a non-negative value and a unit")

    def test_evidence_ids_are_unique(self):
        duplicate = copy.deepcopy(self.initial["evidence"][0])
        self.initial["evidence"].append(duplicate)
        self.assertIssue(self.initial, "evidence_id values must be unique")

    def test_evidence_cannot_postdate_report(self):
        self.initial["evidence"][0]["acquired_at"] = "2026-10-01T12:00:00Z"
        self.assertIssue(self.initial, "cannot postdate this report")

    def test_real_or_restricted_intake_is_rejected(self):
        self.initial["synthetic"] = False
        self.assertIssue(self.initial, "expected constant True")
        self.initial["synthetic"] = True
        self.initial["disclosure"]["handling"] = "restricted"
        self.assertIssue(self.initial, "accepts only synthetic_public")

    def test_notification_reference_is_required(self):
        self.initial["notifications"]["regulator_reference"] = None
        self.assertIssue(self.initial, "needs a reference")

    def test_additional_property_is_rejected(self):
        self.initial["secret_log"] = "must not be silently accepted"
        self.assertIssue(self.initial, "additional property is not allowed")

    def test_unknown_extension_is_rejected(self):
        self.initial["extensions"] = {"priority": "high"}
        self.assertIssue(self.initial, "additional property is not allowed")

    def test_namespaced_extension_is_allowed(self):
        self.initial["extensions"] = {"x-review-note": "fictional"}
        self.assertEqual([], self.check(self.initial))

    def test_chain_cannot_rewrite_original_notification_time(self):
        self.final["reported_at"] = "2026-10-02T10:05:00Z"
        issues = validate.validate_records([("r0", self.initial), ("r1", self.final)], SCHEMA, SCHEMA_PATH)
        self.assertTrue(any("must remain identical" in issue for issue in issues["r1"]), issues)

    def test_chain_cannot_branch(self):
        branch = copy.deepcopy(self.final)
        branch["record_id"] = "SYNTH-EXAMPLE-001-R1-BRANCH"
        issues = validate.validate_records(
            [("r0", self.initial), ("r1", self.final), ("branch", branch)], SCHEMA, SCHEMA_PATH
        )
        self.assertTrue(any("branched history" in issue for issue in issues["revision chains"]), issues)

    def test_chain_cannot_continue_after_final(self):
        update = copy.deepcopy(self.final)
        update["record_id"] = "SYNTH-EXAMPLE-001-R2"
        update["record_status"] = "update"
        update["supersedes"] = "SYNTH-EXAMPLE-001-R1"
        update["last_updated_at"] = "2026-10-07T15:30:00Z"
        update["follow_up"]["next_update_due"] = "2026-10-08T15:30:00Z"
        issues = validate.validate_records([("r0", self.initial), ("r1", self.final), ("r2", update)], SCHEMA, SCHEMA_PATH)
        self.assertTrue(any("cannot continue" in issue for issue in issues["r2"]), issues)

    def test_missing_revision_is_rejected(self):
        issues = validate.validate_records([("r1", self.final)], SCHEMA, SCHEMA_PATH)
        self.assertTrue(any("expected exactly one initial" in issue for issue in issues["revision chains"]), issues)

    def test_cli_returns_zero_for_examples(self):
        paths = sorted(str(path) for path in EXAMPLES.glob("*.json"))
        completed = subprocess.run([sys.executable, str(ROOT / "site" / "tools" / "validate.py"), *paths], capture_output=True, text=True)
        self.assertEqual(0, completed.returncode, completed.stdout + completed.stderr)
        self.assertIn("not a truth, safety, or legal-compliance determination", completed.stdout)


if __name__ == "__main__":
    unittest.main()
